(function(root){
'use strict';
// Original, intentionally incorrect examples. Each has one explicitly authored
// replacement; correct Spanish is stored, never generated by corrupting a model.
const rows=[];
function add(id,source,concept,wrong,bad,answer,good,other,why,context='Choose the replacement that repairs this sentence.'){rows.push({id:'skill-spot-'+id,source,concept,wrong,bad,answer,good,options:[answer,...other],why,context});}
add('a11-01','u0l0',null,'Me llamas Ana.','llamas','llamo','Me llamo Ana.',['llamas','llama','llaman'],'Me llamo gives your own name. Te llamas asks or states someone else’s name.');
add('a11-02','u0l0',null,'¿Cómo te llamo?','llamo','llamas','¿Cómo te llamas?',['llamo','llama','llaman'],'Use the familiar question ¿Cómo te llamas? to ask someone their name.');
add('a11-03','u0l0',null,'Buenos día.','día','días','Buenos días.',['día','nombre','luego'],'The greeting is the fixed plural phrase Buenos días: good morning.');
add('a11-04','u0l0',null,'Buenas días.','Buenas','Buenos','Buenos días.',['Buenas','Buena','Buen'],'Días is masculine and plural, so the greeting uses Buenos días.');
add('a11-05','u0l0',null,'Hasta luegos.','luegos','luego','Hasta luego.',['luegos','llamo','nombre'],'Hasta luego means see you later. Luego does not take a plural ending.');
add('a11-06','u0l0',null,'Me llama Luis.','llama','llamo','Me llamo Luis.',['llama','llamas','llaman'],'When Luis introduces himself, he says Me llamo Luis.',['Luis is giving his own name.'].join(''));
add('a11-07','u0l0',null,'¿Cómo me llamas?','me','te','¿Cómo te llamas?',['me','nos','os'],'To ask the other person’s name, use te: ¿Cómo te llamas?','You want to ask the other person their name.');
add('a11-08','u0l0',null,'Hola, me llamo Ana. ¿Y yo?','yo','tú','Hola, me llamo Ana. ¿Y tú?',['yo','ella','él'],'¿Y tú? means and you? Yo means I.','Ana introduces herself, then asks Luis to introduce himself.');
add('a11-09','u0l0',null,'Muchas gracia.','gracia','gracias','Muchas gracias.',['gracia','nombre','días'],'The everyday expression is Muchas gracias: thank you very much.');
add('a11-10','u0l0',null,'Por favores.','favores','favor','Por favor.',['favores','gracias','luego'],'The polite expression is Por favor, with singular favor.');
add('a11-11','u1l0','present-ser','Yo eres de Londres.','eres','soy','Yo soy de Londres.',['eres','somos','son'],'Soy goes with yo. Eres goes with tú. Use ser to give your origin.');
add('a11-12','u1l1','present-tener','Yo soy veinte años.','soy','tengo','Yo tengo veinte años.',['soy','estoy','tienes'],'Spanish uses tener for age: tengo veinte años, literally I have twenty years.');
add('a11-13','u1l2','present-regular-ar','Nosotros habla español.','habla','hablamos','Nosotros hablamos español.',['habla','hablas','hablan'],'Nosotros takes -amos with regular -AR verbs: hablamos. Habla is él/ella/usted.');
add('a11-14','u2l1','present-regular-er','Vosotros comen pan.','comen','coméis','Vosotros coméis pan.',['comen','come','comemos'],'Vosotros/as takes -éis with regular -ER verbs. Comen belongs to ellos/ellas/ustedes.');
add('a11-15','u1l0','present-regular-ir','Tú vive en Madrid.','vive','vives','Tú vives en Madrid.',['vive','vivo','viven'],'Tú takes -es with vivir: vives. Vive belongs to él/ella/usted.');
add('a11-16','u5l2','ser-estar-hay','La estación es cerca.','es','está','La estación está cerca.',['es','soy','son'],'Use estar to locate a place: la estación está cerca. Ser describes identity or characteristics.');
add('a11-17','u4l1','agreement','La camisa es blanco.','blanco','blanca','La camisa es blanca.',['blanco','blancos','blancas'],'Camisa is feminine singular. Its colour adjective agrees: blanca.');
add('a11-18','u1l1','present-tener','Yo estoy hambre.','estoy','tengo','Yo tengo hambre.',['estoy','soy','tienes'],'The useful Spanish chunk is tener hambre: tengo hambre means I am hungry.');
add('a12-01','a12u0l1','gustar-plural','Me gusta los libros.','gusta','gustan','Me gustan los libros.',['gusta','gusto','gustas'],'Los libros is plural, so use gustan. Use gusta with one thing or an activity.');
add('a12-02','a12u0l1','gustar-plural','Yo gusto el cine.','Yo gusto','Me gusta','Me gusta el cine.',['Yo gusto','Me gustan','Te gustan'],'To say you like the cinema, use Me gusta el cine. The thing liked controls gusta/gustan.');
add('a12-03','a12u2l0','ir-a-infinitive','Mañana voy ir al cine.','voy','voy a','Mañana voy a ir al cine.',['voy','va a','vas a'],'Plans use ir a + infinitive. Keep a between voy and ir.');
add('a12-04','a12u6l0','reflexive-routines','Yo se levanto a las ocho.','se','me','Yo me levanto a las ocho.',['se','te','os'],'For your own routine use me: yo me levanto. Se refers to él/ella/usted or ellos/ellas/ustedes.');
add('a12-05','a12u6l0','reflexive-routines','Vosotros se levantáis temprano.','se','os','Vosotros os levantáis temprano.',['se','me','nos'],'Vosotros/as uses os in reflexive routines: os levantáis.');
add('a12-06','a12u0l2','present-stem-changes','Yo prefero el té.','prefero','prefiero','Yo prefiero el té.',['prefero','prefieres','prefiere'],'Preferir changes e to ie in this yo form: prefiero.');
add('a12-07','a12u7l2','simple-connectors','Voy al café y no voy al cine por estoy cansada.','por','porque','Voy al café y no voy al cine porque estoy cansada.',['por','pero','con'],'Porque introduces a reason with a conjugated verb: porque estoy cansada. Por cannot go directly before estoy.');
add('a21-01','a21u0l0','present-perfect','Hoy yo ha comido en casa.','ha','he','Hoy yo he comido en casa.',['ha','has','han'],'The yo auxiliary is he: he + participle. Ha goes with él/ella/usted.');
add('a21-02','a21u0l0','present-perfect','Esta semana hemos hacer la compra.','hacer','hecho','Esta semana hemos hecho la compra.',['hacer','hago','hice'],'After hemos use a participle. Hacer has the irregular participle hecho.');
add('a21-03','a21u1l0','selected-preterite','Ayer yo fui al museo y comió allí.','comió','comí','Ayer yo fui al museo y comí allí.',['comió','comiste','comieron'],'The speaker is still yo in both actions: fui y comí. Comió belongs to él/ella/usted.');
add('a21-04','a21u2l0','comparisons','El tren es más rápido como el autobús.','como','que','El tren es más rápido que el autobús.',['como','de','con'],'Comparisons with más use que. Equality uses tan… como.');
add('a21-05','a21u5l0','health-doler','Me duele las piernas.','duele','duelen','Me duelen las piernas.',['duele','dolor','doler'],'Las piernas is plural, so use duelen. For one body part, use duele.');
add('a21-06','a21u6l0','practical-modals','Tengo ir a la farmacia.','Tengo','Tengo que','Tengo que ir a la farmacia.',['Tengo','Tienes que','Tiene que'],'Tener que + infinitive expresses a need/obligation: tengo que ir.');
add('a22-01','a22u0l0','imperfect-background','Antes nosotros vivía en Madrid.','vivía','vivíamos','Antes nosotros vivíamos en Madrid.',['vivía','vivías','vivían'],'Nosotros/as uses -íamos with vivir in the imperfect: vivíamos.');
add('a22-02','a22u1l2','past-event-background','Mientras Ana cocinaba, sonaba el teléfono una sola vez.','sonaba','sonó','Mientras Ana cocinaba, sonó el teléfono una sola vez.',['sonaba','sonaban','sonabas'],'Cocinaba gives the ongoing background. Sonó marks the single completed interruption.');
add('a22-03','a22u1l0','preterite-er-ir','Ayer nosotros comieron juntos.','comieron','comimos','Ayer nosotros comimos juntos.',['comieron','comiste','comió'],'Nosotros in the completed past is comimos. Comieron belongs to ellos/ellas/ustedes.');
add('a22-04','a22u2l1','preterite-practical-irregulars','Ayer yo tuvo un problema.','tuvo','tuve','Ayer yo tuve un problema.',['tuvo','tuvieron','tuviste'],'Tener has the irregular preterite stem tuv-. The yo form is tuve; tuvo is él/ella/usted.');
add('b11-01','b11u2l0','future-plans','Mañana yo iremos al médico.','iremos','iré','Mañana yo iré al médico.',['iremos','irás','irán'],'The future yo ending is -é: iré. Iremos refers to nosotros/as.');
add('b11-02','b11u2l0','future-plans','El próximo año nosotros viajarán más.','viajarán','viajaremos','El próximo año nosotros viajaremos más.',['viajarán','viajarás','viajaré'],'Nosotros/as uses -emos in the future: viajaremos. Viajarán is ellos/ellas/ustedes.');
add('b11-03','b11u3l0','conditional-advice','Yo, en tu lugar, comprarías el billete ahora.','comprarías','compraría','Yo, en tu lugar, compraría el billete ahora.',['comprarías','compraríamos','comprarían'],'With yo, advice takes compraría. Comprarías belongs to tú.');
add('b11-04','b11u3l0','conditional-advice','Nosotros podrías ayudar.','podrías','podríamos','Nosotros podríamos ayudar.',['podrías','podría','podrían'],'The conditional nosotros/as form is podríamos. Keep the -r- in the irregular stem podr-.');
add('b12-01','b12u6l0','wishes-necessity','Quiero que tú vienes mañana.','vienes','vengas','Quiero que tú vengas mañana.',['vienes','venga','vengan'],'A wish about another person uses que + subjunctive: quiero que tú vengas.');
add('b12-02','b12u6l0','wishes-necessity','Es necesario que vosotros estudian.','estudian','estudiéis','Es necesario que vosotros estudiéis.',['estudian','estudias','estudiemos'],'Es necesario que introduces the subjunctive. Vosotros/as of estudiar is estudiéis.');
add('b12-03','b12u6l0','wishes-necessity','Espero que Ana llega pronto.','llega','llegue','Espero que Ana llegue pronto.',['llega','llegas','lleguen'],'A hope about Ana uses espero que + subjunctive. The singular form is llegue.');
add('b12-04','b12u6l0','wishes-necessity','Ojalá podemos quedar mañana.','podemos','podamos','Ojalá podamos quedar mañana.',['podemos','pueda','puedan'],'Ojalá expresses a wish. The nosotros/as subjunctive of poder is podamos.');
add('b21-01','b21u0l0','prior-past-events','Cuando llegué, Ana ya ha salido.','ha','había','Cuando llegué, Ana ya había salido.',['ha','he','hemos'],'The departure happened before another past moment. Use había + participle for that earlier event.');
add('b21-02','b21u0l0','prior-past-events','Nosotros ya habían comprado los billetes cuando llamó Luis.','habían','habíamos','Nosotros ya habíamos comprado los billetes cuando llamó Luis.',['habían','habías','había'],'For nosotros/as, the auxiliary is habíamos. The purchase precedes the call.');
add('b21-03','b21u2l0','uncertainty-viewpoints','No creo que Ana está en casa.','está','esté','No creo que Ana esté en casa.',['está','estoy','están'],'No creo que presents a claim you do not accept as certain, so use the subjunctive esté.');
add('b21-04','b21u6l0','imagined-present','Si tendría más tiempo, viajaría más.','tendría','tuviera','Si tuviera más tiempo, viajaría más.',['tendría','tendré','tengo'],'For this imagined condition, use si + imperfect subjunctive; the result takes the conditional.');
add('b22-01','b22u1l1','past-alternatives','Con más tiempo, yo había revisado el informe.','había','habría','Con más tiempo, yo habría revisado el informe.',['había','he','ha'],'For an unrealised past alternative use habría + participle. Había revisado describes an earlier actual event.','Looking back, say what you would have done with more time, but did not do.');
add('b22-02','b22u4l0','register-reporting','Le agradecería que me ayudaras, señora.','ayudaras','ayudara','Le agradecería que me ayudara, señora.',['ayudaras','ayudarais','ayudaran'],'This formal request addresses usted. Use ayudara; ayudaras addresses tú.');
add('b22-03','b22u6l0','imagined-past-condition','Si habría tenido tiempo, habría ido.','habría','hubiera','Si hubiera tenido tiempo, habría ido.',['habría','había','he'],'The unreal past condition takes si + hubiera + participle; habría ido states the unreal result.');
add('b22-04','b22u6l1','possible-completed-change','Es posible que ha cambiado el horario.','ha','haya','Es posible que haya cambiado el horario.',['ha','había','habría'],'A possible completed change uses es posible que + present perfect subjunctive: haya cambiado.');
root.PracticeErrors={rows};if(typeof module!=='undefined')module.exports=root.PracticeErrors;
})(typeof window==='undefined'?globalThis:window);
